// Pixi owns presentation only. RunnerGame remains the sole source of collisions,
// input, time, scoring and checkpoint state. No ticker or second game loop.
import {Application,Container,Graphics,Sprite,Texture,Rectangle,Text} from './vendor/pixi.js';
import {drawDawg} from './dawg-art.js';
import {levelOf} from './dawg-career.js';
import {lookHash} from './dawg-fashion.js';
import {worldLook,hash} from './world.js';
export const dashProjection=(lane,z)=>{const p=Math.max(0,1-z/270),scale=.12+p*p*.88;return {x:210+(lane-1)*118*scale,y:172+scale*328,scale};};
export const dashVisualKey=d=>d?`2:${d.id}:${d.genome?.version||1}:${lookHash(d)}:${levelOf(d)>=25?2:levelOf(d)>=10?1:0}`:'starter';
function canvas(w,h){const el=document.createElement('canvas');el.width=w;el.height=h;return el;}
function fallbackAtlas(d){const out=canvas(512,480),c=out.getContext('2d');for(let i=0;i<12;i++)drawDawg(c,d,i%4*128+64,Math.floor(i/4)*160+80,145,i/12*.48,'run');return {source:out,width:128,height:160,frames:12,columns:4,kind:'2d-run'};}
function paintTexture(w,h,draw){const el=canvas(w,h);draw(el.getContext('2d'));return Texture.from(el);}
export class PixiDash {
 constructor(target,onFailure){this.target=target;this.onFailure=onFailure;this.ready=false;this.failed=false;this.sprites=[];this.used=0;this.cache=new Map();this.jobs=new Set();this.currentKey='';this.atlas=null;this.lastGame=null;this.dead=false;this.bursts=[];this.abort=new AbortController();}
 async init(){
  const view=canvas(420,560);view.className='dash-gpu';view.setAttribute('aria-hidden','true');this.view=view;
  const app=this.app=new Application();await app.init({canvas:view,width:420,height:560,preference:'webgl',resolution:Math.min(globalThis.devicePixelRatio||1,1.5),autoDensity:false,antialias:true,background:'#101427',autoStart:false,sharedTicker:false,powerPreference:'low-power',manageImports:false});if(this.dead){app.destroy(true);return;}app.stop();
  this.loss=e=>{e.preventDefault();this.fail();};view.addEventListener('webglcontextlost',this.loss);this.target.parentElement.append(view);
  this.bg=new Container();this.road=new Graphics();this.world=new Container();this.fx=new Container();this.hud=new Container();app.stage.addChild(this.bg,this.road,this.world,this.fx,this.hud);
  this.textures=this.makeTextures();this.texts=[];for(const [x,y,size,fill,align]of [[18,13,15,'#dcffb1','left'],[402,13,13,'#ffe0a0','right'],[18,34,8,'#c7bcd8','left'],[402,34,8,'#c7bcd8','right'],[210,547,9,'#e6d9f3','center']]){const text=new Text({text:'',style:{fontFamily:'system-ui, sans-serif',fontSize:size,fontWeight:'700',fill,align}});text.anchor.set(align==='right'?1:align==='center'?.5:0,.5);text.position.set(x,y);this.hud.addChild(text);this.texts.push(text);}
  this.ready=true;return this;
 }
 makeTextures(){const textures={};textures.glow=paintTexture(128,128,c=>{const g=c.createRadialGradient(64,64,0,64,64,64);g.addColorStop(0,'#ffffff9f');g.addColorStop(.3,'#ffffff40');g.addColorStop(1,'#ffffff00');c.fillStyle=g;c.fillRect(0,0,128,128);});
  textures.shadow=paintTexture(100,30,c=>{const g=c.createRadialGradient(50,15,0,50,15,50);g.addColorStop(0,'#00000090');g.addColorStop(1,'#00000000');c.scale(1,.3);c.fillStyle=g;c.fillRect(0,0,100,100);});
  textures.rain=paintTexture(4,24,c=>{c.fillStyle='#d5e7ff80';c.fillRect(1,0,1,24);});
  textures.coin=paintTexture(48,56,c=>{c.shadowColor='#ffbb50';c.shadowBlur=8;c.fillStyle='#fed782';c.beginPath();c.ellipse(24,28,17,21,0,0,Math.PI*2);c.fill();c.shadowBlur=0;c.strokeStyle='#ab6b35';c.lineWidth=3;c.beginPath();c.ellipse(24,28,12,16,0,0,Math.PI*2);c.stroke();c.fillStyle='#fff4c1';c.font='bold 24px sans-serif';c.textAlign='center';c.fillText('Ð',24,36);});
  for(const type of ['crate','block','bar'])textures[type]=paintTexture(100,128,c=>{if(type==='bar'){c.fillStyle='#566e8a';c.fillRect(12,18,9,110);c.fillRect(80,18,9,110);const g=c.createLinearGradient(0,0,100,0);g.addColorStop(0,'#44baae');g.addColorStop(.5,'#c7fff3');g.addColorStop(1,'#44baae');c.fillStyle=g;c.fillRect(4,20,92,27);c.fillStyle='#15233c';c.font='bold 23px sans-serif';c.textAlign='center';c.fillText('↓',50,42);return;}const top=type==='crate'?62:4;const g=c.createLinearGradient(0,0,100,0);g.addColorStop(0,type==='crate'?'#9a643f':'#52355e');g.addColorStop(.45,type==='crate'?'#d49c62':'#99678d');g.addColorStop(1,type==='crate'?'#7e5039':'#432d58');c.fillStyle=g;c.beginPath();c.roundRect(9,top,82,128-top,7);c.fill();c.fillStyle=type==='crate'?'#ffe0a0':'#ffa7d4';c.fillRect(9,top,82,7);c.strokeStyle='#1d172a77';c.lineWidth=5;c.strokeRect(17,top+13,66,128-top-23);c.beginPath();c.moveTo(20,top+17);c.lineTo(80,116);c.moveTo(80,top+17);c.lineTo(20,116);c.stroke();c.fillStyle='#fff0d9';c.font='bold 26px sans-serif';c.textAlign='center';c.fillText(type==='crate'?'↑':'×',50,top+(128-top)*.6);});
  for(const kind of ['shield','magnet'])textures[kind]=paintTexture(64,64,c=>{c.shadowColor='#b9ffd8';c.shadowBlur=10;c.strokeStyle='#c9ffe3';c.lineWidth=4;c.beginPath();if(kind==='shield'){c.moveTo(32,7);c.lineTo(53,18);c.lineTo(49,43);c.lineTo(32,56);c.lineTo(15,43);c.lineTo(11,18);c.closePath();}else{c.arc(32,31,18,0,Math.PI);c.moveTo(14,31);c.lineTo(14,13);c.moveTo(50,31);c.lineTo(50,13);}c.stroke();});
  textures.building=paintTexture(100,200,c=>{const g=c.createLinearGradient(0,0,100,0);g.addColorStop(0,'#161f35');g.addColorStop(.7,'#31324c');g.addColorStop(1,'#171e32');c.fillStyle=g;c.fillRect(0,0,100,200);c.fillStyle='#b6a5ff';c.fillRect(0,0,100,4);c.fillStyle='#71e9d1';c.fillRect(5,0,2,200);for(let y=15;y<190;y+=21)for(let x=14;x<90;x+=21){c.fillStyle=(x+y)%3?'#efbf7a60':'#9ac8ff3b';c.fillRect(x,y,9,12);}c.fillStyle='#0a1329';c.fillRect(15,72,75,34);c.strokeStyle='#eb80cd';c.lineWidth=2;c.strokeRect(15,72,75,34);c.fillStyle='#f4c7e7';c.font='bold 12px monospace';c.fillText('AFTER',22,86);c.fillText('HOURS',22,100);});return textures;
 }
 setBackground(seed,district){this.bg.removeChildren().forEach(o=>o.destroy({texture:true,textureSource:true}));const look=worldLook(seed,district),texture=paintTexture(420,560,c=>{const g=c.createLinearGradient(0,0,0,560);g.addColorStop(0,look.sky);g.addColorStop(.5,look.floor);g.addColorStop(1,'#111726');c.fillStyle=g;c.fillRect(0,0,420,560);const glow=c.createRadialGradient(300,100,0,300,100,160);glow.addColorStop(0,look.glow+'50');glow.addColorStop(1,'#00000000');c.fillStyle=glow;c.fillRect(0,0,420,330);c.fillStyle='#eadfc3';c.beginPath();c.arc(300,88,27,0,Math.PI*2);c.fill();for(let i=0;i<50;i++){c.fillStyle='#e5e1ff80';c.fillRect(hash(seed,i+89)*420,hash(seed,i+114)*180,1,1);}});this.bg.addChild(new Sprite(texture));this.city=[];
  for(let layer=0;layer<3;layer++){const tex=paintTexture(840,320,c=>{for(let i=0;i<24;i++){const x=i*37,h=25+hash(seed,i+layer*500)*130,w=28+hash(seed,i+layer*13)*13;c.fillStyle=['#21223e','#1d233a','#182238'][layer];c.fillRect(x,320-h,w,h);c.fillStyle=look.glow+'50';c.fillRect(x,320-h,w,2);for(let y=320-h+8;y<310;y+=14)for(let j=0;j<3;j++)if(hash(seed,1000+i*77+j+y)>.4){c.fillStyle=j%2?look.accent+'55':'#ffd2a438';c.fillRect(x+4+j*9,y,3,5);}}});const s=new Sprite(tex);s.y=layer===0?-75:layer===1?-30:8;s.alpha=.8;this.bg.addChild(s);this.city.push(s);}
  this.backgroundKey=seed+':'+district;
 }
 sprite(texture,x,y,width,height,tint=0xffffff,alpha=1,layer=this.world){let s=this.sprites[this.used];if(!s){s=new Sprite(texture);this.sprites.push(s);}layer.addChild(s);s.visible=true;s.texture=texture;s.anchor.set(.5,1);s.position.set(x,y);s.width=Math.max(.01,width);s.height=Math.max(.01,height);s.tint=tint;s.alpha=alpha;s.rotation=0;this.used++;return s;}
 atlasFrom(result){const base=Texture.from(result.source),textures=Array.from({length:result.frames},(_,i)=>new Texture({source:base.source,frame:new Rectangle(i%result.columns*result.width,Math.floor(i/result.columns)*result.height,result.width,result.height)}));return {base,textures,kind:result.kind};}
 putAtlas(key,entry){const old=this.cache.get(key);if(old){old.textures.forEach(t=>t.destroy());old.base.destroy(true);}this.cache.delete(key);this.cache.set(key,entry);while(this.cache.size>4){const [k,v]=[...this.cache.entries()].find(([key])=>key!==this.currentKey);v.textures.forEach(t=>t.destroy());v.base.destroy(true);this.cache.delete(k);}if(key===this.currentKey)this.atlas=entry;}
 prepare(d){if(!d)return;const key=dashVisualKey(d);this.currentKey=key;const cached=this.cache.get(key);if(cached){this.atlas=cached;return;}this.putAtlas(key,this.atlasFrom(fallbackAtlas(d)));if(this.jobs.has(key))return;this.jobs.add(key);
  import('./dawg-gpu.js').then(m=>m.createRunAtlas(d,{signal:this.abort.signal})).then(result=>{if(this.dead)return;this.putAtlas(key,this.atlasFrom(result));if(key===this.currentKey)this.onAsset?.('3D DAWG · LIVE CITY');if(this.lastGame)this.draw(...this.lastGame);}).catch(()=>{if(!this.dead&&key===this.currentKey)this.onAsset?.('2D DAWG · LIVE CITY');}).finally(()=>this.jobs.delete(key));
 }
 event(e,g){if(this.reduced)return;if(['coin','power','shield','jump','dodge'].includes(e.type))this.bursts.push({x:g.x,y:e.type==='jump'?501:458,start:g.time,color:e.type==='shield'?0xff98c2:e.type==='coin'?0xffdb8d:0xb0ffce});this.bursts=this.bursts.slice(-12);}
 draw(g,d,reduced=false){if(!this.ready||this.failed)return false;this.lastGame=[g,d,reduced];this.reduced=reduced;this.prepare(d);const seed=g.worldSeed,district=Math.floor(g.distance/800),look=worldLook(seed,district),t=reduced?0:g.time;if(this.backgroundKey!==seed+':'+district)this.setBackground(seed,district);for(let i=0;i<this.city.length;i++)this.city[i].x=-((g.distance*(i+1)*.045)%420);this.used=0;
  const road=this.road;road.clear();road.poly([166,170,254,170,430,560,-10,560]).fill(0x111b2b);road.poly([175,178,246,178,386,560,34,560]).fill({color:0x243147,alpha:.22});
  for(const lane of [-.5,.5,1.5,2.5]){const a=dashProjection(lane,270),b=dashProjection(lane,0);road.moveTo(a.x,a.y).lineTo(b.x,b.y).stroke({color:lane===-.5||lane===2.5?look.glow:look.accent,width:lane===-.5||lane===2.5?2:1,alpha:lane===-.5||lane===2.5?.9:.25});}
  for(let i=0;i<18;i++){const z=(i*18-g.distance%18+324)%324,a=dashProjection(-.5,z),b=dashProjection(2.5,z);road.moveTo(a.x,a.y).lineTo(b.x,b.y).stroke({color:look.accent,alpha:.12,width:1});}
  // Emissive street signs, wet reflections and distant traffic all use pooled sprites.
  for(let side=0;side<2;side++)for(let i=0;i<6;i++){const z=(i*53-g.distance%53+318)%318,p=dashProjection(side?3.2:-1.2,z),h=(75+hash(seed,i+side*9)*70)*p.scale;this.sprite(this.textures.glow,p.x,p.y+28*p.scale,75*p.scale,55*p.scale,side?0xf17acb:0x88f5d6,.18);this.sprite(this.textures.building,p.x,p.y,55*p.scale,h);}
  for(const row of [...g.rows].sort((a,b)=>b.z-a.z)){for(const o of row.obstacles){const p=dashProjection(o.lane,row.z),h=(o.type==='block'?94:o.type==='bar'?92:66)*p.scale;this.sprite(this.textures.shadow,p.x,p.y+7*p.scale,78*p.scale,18*p.scale,0xffffff,.7);this.sprite(this.textures[o.type],p.x,p.y,72*p.scale,h);}
   const p=dashProjection(row.safe,row.z),spin=reduced?1:.65+.35*Math.cos(g.time*4+row.id);this.sprite(this.textures.glow,p.x,p.y+7*p.scale,45*p.scale,50*p.scale,0xffcb77,.35);this.sprite(this.textures.coin,p.x,p.y-6*p.scale,23*p.scale*spin,27*p.scale);if(row.power){this.sprite(this.textures.glow,p.x,p.y-26*p.scale,75*p.scale,75*p.scale,0xa2ffd6,.55);this.sprite(this.textures[row.power],p.x,p.y-28*p.scale,42*p.scale,42*p.scale);}}
  const p=dashProjection(g.visualLane,0),lift=g.jump>0?Math.sin(g.jump/.85*Math.PI)*72:0,slide=g.slide>0,bob=slide||reduced?0:Math.sin(t*26)*1.5;
  this.sprite(this.textures.shadow,p.x,519,75-lift*.28,19,0xffffff,.65);if(g.shield||g.magnet>0)this.sprite(this.textures.glow,p.x,528-lift,125,145,g.shield?0xa7ffdb:0xc59aff,.55);
  if(!reduced&&g.status==='playing'&&!lift&&!slide)for(let i=1;i<6;i++)this.sprite(this.textures.glow,p.x+Math.sin(t*13-i)*7,516+i*5,20-i*2,13,0xafffe1,(6-i)*.022);
  if(this.atlas){const frame=reduced?0:Math.floor(g.time*25)%this.atlas.textures.length;this.sprite(this.atlas.textures[frame],p.x,516-lift+bob,slide?91:104,slide?70:130);}
  for(const b of this.bursts){const age=g.time-b.start;if(age<0||age>.65)continue;for(let i=0;i<8;i++){const angle=i/8*Math.PI*2;this.sprite(this.textures.glow,b.x+Math.cos(angle)*age*75,b.y+Math.sin(angle)*age*60-age*25,9,9,b.color,1-age/.65,this.fx);}}this.bursts=this.bursts.filter(b=>g.time-b.start<.65);
  if(!reduced&&hash(seed,district+903)>.42)for(let i=0;i<35;i++){const x=(hash(seed,i+303)*460-t*46)%460,y=(hash(seed,i+503)*600+t*250)%600;const s=this.sprite(this.textures.rain,x+20,y,1,12+hash(seed,i)*12,0xffffff,.25,this.fx);s.rotation=.16;}
  road.rect(0,0,420,52).fill({color:0x101529,alpha:.94});road.rect(0,530,420,30).fill({color:0x101529,alpha:.95});this.texts[0].text=Math.floor(g.distance)+' m';this.texts[1].text=g.coins+' GOLD';this.texts[2].text=look.label.toUpperCase();this.texts[3].text=g.magnet>0?'MAGNET '+Math.ceil(g.magnet)+'s':g.shield?'SHIELD READY':'FIND YOUR LINE';this.texts[4].text='← → DODGE     ↑ JUMP     ↓ SLIDE';
  for(let i=this.used;i<this.sprites.length;i++)this.sprites[i].visible=false;this.app.renderer.render(this.app.stage);return true;
 }
 fail(){if(this.failed)return;this.failed=true;this.onFailure?.();this.dispose();}
 dispose(){if(this.dead)return;this.dead=true;this.abort.abort();this.ready=false;this.view?.removeEventListener('webglcontextlost',this.loss);for(const entry of this.cache.values()){entry.textures.forEach(t=>t.destroy());entry.base.destroy(true);}this.cache.clear();this.bg?.removeChildren().forEach(o=>o.destroy({texture:true,textureSource:true}));if(this.textures)Object.values(this.textures).forEach(t=>t.destroy(true));try{if(this.app?.renderer)this.app.destroy(true,{children:true,texture:false,textureSource:false});}catch{}this.view?.remove();}
}
